local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end
local hooks,timers={},{};local now=0;local hookapi={Add=function(e,n,f)hooks[e.."/"..n]=f end,Remove=function(e,n)hooks[e.."/"..n]=nil end};local timerapi={Create=function(n,d,r,f)timers[n]=f end,Remove=function(n)timers[n]=nil end};local function valid(x)return type(x)=="table"and x.valid~=false end;local function player()return{valid=true,IsPlayer=function()return true end}end;local function object()return{valid=true}end
local bindings;local function include()return load_submission("lua/rhenium_hot_object_round/controller.lua",bindings)end;bindings={include=include,hook=hookapi,timer=timerapi,IsValid=valid,CurTime=function()return now end};local S=load_submission("lua/rhenium_hot_object_round/server.lua",bindings);local a,b,c=player(),player(),player();local o=object()
case("adapter installs lifecycle hooks and one timer",function()S.Install({object_id="hot:1",object_revision=1});for _,n in ipairs({"Death","Spawn","Disconnect","Removed"})do assert(hooks[({Death="PlayerDeath",Spawn="PlayerSpawn",Disconnect="PlayerDisconnected",Removed="EntityRemoved"})[n].."/"..S.HookPrefix.."."..n])end;assert(timers[S.TimerName])end)
case("trusted bindings start a three player round",function()assert(S.BindPlayer(a,"A",1));assert(S.BindPlayer(b,"B",1));assert(S.BindPlayer(c,"C",1));assert(S.BindObject(o,"hot:1",1));assert(S.StartRound("start","round","exploding",{a,b,c},a,10))end)
case("object binding is single use and removal restores original callbacks",function()local starts,touches=0,0;local spare=object();local old_start=function()starts=starts+1 end;local old_touch=function()touches=touches+1 end;spare.StartTouch=old_start;spare.Touch=old_touch;assert(S.BindObject(spare,"hot:1",1));assert(not S.BindObject(spare,"hot:1",1));spare:StartTouch(a);spare:Touch(b);assert(starts==1 and touches==1);hooks["EntityRemoved/"..S.HookPrefix..".Removed"](spare);assert(spare.StartTouch==old_start and spare.Touch==old_touch)end)
case("entity StartTouch and Touch share deterministic dispatch",function()o:StartTouch(b);o:Touch(c);assert(S.Snapshot().holder=="C")end)
case("unbound physical touch cannot impersonate a player",function()local x=player();local ok=S.Dispatch({kind="touch",object=o,player=x});assert(not ok);assert(S.Snapshot().holder=="C")end)
case("PlayerDeath hook changes holder once",function()now=3;hooks["PlayerDeath/"..S.HookPrefix..".Death"](c);assert(S.Snapshot().holder=="A")end)
case("PlayerSpawn rebinds a new revision",function()hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"](c);hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"](c);o:Touch(c);assert(S.Snapshot().holder=="C")end)
case("timer reaches fixed deadline exactly once",function()now=10;timers[S.TimerName]();local s=S.Snapshot();assert(s.status=="finished"and s.settlements==1);timers[S.TimerName]();assert(S.Snapshot().settlements==1)end)
case("Save exposes deterministic audit for restart",function()local s=S.Save();assert(s.schema_version==1 and#s.audit>=4 and s.result)end)
case("shutdown removes hooks timer restores callbacks and freezes adapter",function()S.Shutdown();S.Shutdown();for k in pairs(hooks)do if k:find("RheniumHotObjectRound",1,true)then error("hook leak")end end;assert(not timers[S.TimerName]);assert(o.StartTouch==nil and o.Touch==nil)end)
return{cases=cases}
